import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { expect, test, type BrowserContext, type Page } from "@playwright/test";
import {
  SNIPPET_FILE,
  buildPolicy,
  collectSite,
  policyFromSnippet,
} from "../../apps/docs/scripts/csp-policy.ts";

/**
 * The production CSP (generated by apps/docs/scripts/csp.ts, served by nginx) is enforced here on every HTML
 * response from astro preview. A new inline script, inline handler, eval use or third-party origin that the
 * policy does not cover fails this suite instead of breaking production silently.
 *
 * With DOCS_URL (see playwright.docs.config.ts) the suite runs against the deployed site: nginx sends the policy
 * itself (enforced or Report-Only, both fire securitypolicyviolation) and the response headers are checked.
 */
const remote = Boolean(process.env.DOCS_URL);
const nginxSite = readFileSync(
  resolve(
    import.meta.dirname,
    "../../deploy/nginx/markas.jenderalcorp.com.conf",
  ),
  "utf8",
);
/** DOCS_DIST: test another build folder (e.g. a parallel agent build), same as DOCS_PORT in the config. */
const dist = resolve(
  process.env.DOCS_DIST ?? resolve(import.meta.dirname, "../../apps/docs/dist"),
);
const snippet = readFileSync(resolve(dist, SNIPPET_FILE), "utf8");
// Preview runs on plain http://localhost, where upgrade-insecure-requests would send every request to https.
const policy = policyFromSnippet(snippet)
  .split("; ")
  .filter((directive) => directive !== "upgrade-insecure-requests")
  .join("; ");

const FRAMEWORKS = ["blade", "react", "vue", "svelte", "astro", "angular"];
/** Components with their own scripts (Astro), Alpine state (Blade), islands and Svelte image handlers. */
const COMPONENTS = [
  "avatar",
  "modal",
  "combobox",
  "carousel",
  "toast",
  "code-block",
];
const PAGES = [
  "/",
  "/id",
  "/components",
  "/id/components",
  "/docs/introduction",
  "/docs/theming",
  "/id/docs/installation",
  "/frameworks/blade",
  "/templates",
  "/templates/larisa",
  "/pages",
  "/pages/belajar",
  "/support",
  "/id/support/thanks?order=KOPI-20261119-ABCDEFGHIJKLMNOP",
  "/support/cancel",
  "/this-page-does-not-exist",
];

interface Violation {
  directive: string;
  blocked: string;
  source: string;
}

async function enforceCsp(context: BrowserContext): Promise<string[]> {
  const violations: string[] = [];
  await context.exposeBinding("__reportCsp", (_source, violation: Violation) =>
    violations.push(
      `${violation.directive} blocked ${violation.blocked} (${violation.source})`,
    ),
  );
  await context.addInitScript(() => {
    sessionStorage.setItem("markas-splash", "1");
    document.addEventListener("securitypolicyviolation", (event) =>
      (
        window as unknown as { __reportCsp: (violation: Violation) => void }
      ).__reportCsp({
        directive: event.effectiveDirective,
        blocked: event.blockedURI,
        source: `${event.sourceFile}:${event.lineNumber} ${event.sample}`,
      }),
    );
  });
  if (remote) return violations;
  await context.route("**/*", async (route) => {
    if (route.request().resourceType() !== "document") return route.continue();
    const response = await route.fetch();
    const headers = response.headers();
    const isHtml = (headers["content-type"] ?? "").includes("text/html");
    await route.fulfill({
      response,
      headers: isHtml
        ? { ...headers, "content-security-policy": policy }
        : headers,
    });
  });
  return violations;
}

/** Pause after scrolling for lazy islands, Alpine panes and iframes to load and run. */
const SETTLE_MS = 800;

/** Scrolls through the page so lazy islands, Alpine panes and iframes start. */
async function settle(page: Page) {
  await page.waitForLoadState("load");
  await page.evaluate(async () => {
    for (let y = 0; y < document.body.scrollHeight; y += innerHeight) {
      scrollTo(0, y);
      await new Promise((done) => setTimeout(done, 120));
    }
  });
  await page.waitForTimeout(SETTLE_MS);
}

/** Headers every response gets (nginx adds them at server level with `always`). */
const COMMON_HEADERS = {
  "strict-transport-security": "max-age=31536000; includeSubDomains",
  "x-content-type-options": "nosniff",
  "x-frame-options": "SAMEORIGIN",
  "referrer-policy": "strict-origin-when-cross-origin",
  "cross-origin-opener-policy": "same-origin",
};

test.describe("nginx site config", () => {
  test("adds every security header at server level and reads the generated CSP", () => {
    for (const name of [...Object.keys(COMMON_HEADERS), "permissions-policy"]) {
      expect(nginxSite).toMatch(new RegExp(`^ {4}add_header ${name} `, "im"));
    }
    expect(nginxSite).toMatch(
      /^ {4}add_header Content-Security-Policy \$markas_csp always;/m,
    );
    expect(nginxSite).toContain("include /etc/nginx/snippets/markas-csp.conf;");
    expect(snippet).toContain("map $host $markas_csp_policy {");
    // add_header inside a location would drop the server-level headers for that location.
    const locations = nginxSite.split(/^ {4}location /m).slice(1);
    for (const block of locations) expect(block).not.toContain("add_header");
  });
});

test.describe("deployed headers", () => {
  test.skip(!remote, "Set DOCS_URL to check the headers nginx sends.");

  test("pages, registry and hidden files", async ({ request }) => {
    const home = await request.get("/");
    const headers = home.headers();
    for (const [name, value] of Object.entries(COMMON_HEADERS)) {
      expect(headers[name], name).toBe(value);
    }
    expect(headers["permissions-policy"]).toContain("camera=()");
    const served =
      headers["content-security-policy"] ??
      headers["content-security-policy-report-only"];
    expect(served).toBe(policyFromSnippet(snippet));

    const registry = await request.get("/r/button.json");
    expect(registry.status()).toBe(200);
    expect(registry.headers()["access-control-allow-origin"]).toBe("*");
    expect(registry.headers()["x-content-type-options"]).toBe("nosniff");
    expect(registry.headers()["content-security-policy"]).toBeUndefined();

    for (const path of ["/.git/config", "/.env", "/.csp-nginx.conf"]) {
      expect((await request.get(path)).status(), path).toBe(404);
    }
    expect((await request.post("/")).status()).toBe(405);

    // Donation service behind nginx: POST only on its own paths, no caching, Origin checked by the service.
    const health = await request.get("/api/donate/health");
    expect(health.status()).toBe(200);
    expect(health.headers()["cache-control"]).toBe("no-store");
    expect(health.headers()["x-content-type-options"]).toBe("nosniff");
    expect(
      (
        await request.post("/api/donate", { data: { amount: 25_000 } })
      ).status(),
    ).toBe(403);
    expect((await request.post("/api/donate/status")).status()).toBe(405);
    expect((await request.get("/api/other")).status()).toBe(404);
  });
});

test.describe("content security policy", () => {
  test("the nginx snippet matches the inline code in dist", async () => {
    const expected = buildPolicy(await collectSite(dist));
    expect(policyFromSnippet(snippet)).toBe(expected);
  });

  test("site pages run without CSP violations", async ({ page, context }) => {
    test.setTimeout(180_000);
    const violations = await enforceCsp(context);
    for (const path of PAGES) {
      await page.goto(path);
      await settle(page);
    }
    expect(violations).toEqual([]);
  });

  for (const framework of FRAMEWORKS) {
    test(`${framework} previews and template demo run without CSP violations`, async ({
      page,
      context,
    }) => {
      test.setTimeout(180_000);
      const violations = await enforceCsp(context);
      for (const name of COMPONENTS) {
        await page.goto(`/components/${name}?framework=${framework}`);
        await settle(page);
      }
      await page.goto(`/templates/larisa?framework=${framework}`);
      await settle(page);
      await page.goto(`/demo/templates/larisa/${framework}`);
      await settle(page);
      await page.goto(`/demo/templates/belajar/${framework}`);
      await settle(page);
      expect(violations).toEqual([]);
    });
  }

  test("support form posts to /api/donate and opens the checkout without CSP violations", async ({
    page,
    context,
  }) => {
    const violations = await enforceCsp(context);
    const checkout = "https://pay.sumopod.com/pay/csp-test";
    await page.route("**/api/donate", (route) =>
      route.fulfill({ json: { url: checkout } }),
    );
    await page.route("https://pay.sumopod.com/**", (route) =>
      route.fulfill({
        contentType: "text/html",
        body: "<title>Sumopod</title>",
      }),
    );
    // ClientRouter: arrive from another page so the form script runs under the first document's policy.
    await page.goto("/components");
    await page.locator('footer a[href="/support"]').click();
    await page.waitForURL("**/support");
    await page.getByRole("button", { name: "Buy me a coffee" }).click();
    await page.waitForURL(checkout);
    expect(violations).toEqual([]);
  });

  test("navigation, search, theme toggle and copy page run without CSP violations", async ({
    page,
    context,
  }) => {
    test.setTimeout(120_000);
    await context.grantPermissions(["clipboard-read", "clipboard-write"]);
    const violations = await enforceCsp(context);

    await page.goto("/");
    await page
      .getByRole("button", { name: "Toggle light or dark theme" })
      .click();
    // ClientRouter: the next pages' inline scripts run under the first document's policy.
    await page.getByRole("link", { name: "Browse components" }).click();
    await page.waitForURL("**/components");
    await page.locator('main a[href="/components/carousel"]').first().click();
    await page.waitForURL("**/components/carousel");
    await settle(page);

    await page.keyboard.press("Control+k");
    await page.getByLabel("Search query").fill("accordion");
    await expect(
      page.locator("[data-search-results] a").first(),
    ).toHaveAttribute("href", /\/components\/accordion/);

    await page.goto("/templates/larisa");
    await page.getByRole("button", { name: "Copy page" }).click();
    await settle(page);
    expect(violations).toEqual([]);
  });
});
